function converse(role,id,ls,sides,valid){const [a,b,c]=[...sides].sort((x,y)=>x-y),left=a*a+b*b,right=c*c;return Q(role,id,ls,B(`Can sides ${sides.join(', ')} cm form a right triangle? Check existence and identify the longest side first.`,`邊長 ${sides.join('、')} cm 可否組成直角三角形？先檢查三角形存在及辨認最長邊。`),B(valid?'Yes: the positive lengths satisfy the triangle inequalities and the Pythagorean converse.':'No: the required squared equality fails (or the lengths do not form a triangle).',valid?'可以：正邊長符合三角形不等式，且符合勾股逆定理。':'不可以：所需平方等式不成立，或邊長不能組成三角形。'),[B(`The longest side is ${c}; the shorter sum is ${a+b}.`,`最長邊為 ${c}；較短兩邊和為 ${a+b}。`),B(`${M(`${a}^{2}+${b}^{2}=${left}`)} and ${M(`${c}^{2}=${right}`)}.`,`${M(`${a}^{2}+${b}^{2}=${left}`)}，且 ${M(`${c}^{2}=${right}`)}。`)],[B('All lengths must be positive.','所有長度須為正。'),B('Compare the two shorter squares with the longest square.','把較短兩邊平方和與最長邊平方比較。'),B('The converse needs equality, not approximate visual similarity.','逆定理需要相等，不是圖形看來接近。')],{kind:'pythagoras',request:'converse',sides,valid,expected:valid});}
