function relation(role,id,ls,pairs,valid,prompt){return Q(role,id,ls,prompt||B('Does this table define y as a function of x? Explain using each input.','此表是否把 y 定為 x 的函數？按每個輸入說明。'),B(valid?'Yes. Every input has exactly one output; different inputs may share an output.':'No. At least one input is paired with two different outputs.',valid?'是；每個輸入恰有一個輸出，不同輸入可有相同輸出。':'否；至少一個輸入對應兩個不同輸出。'),[B('Check repeated inputs, not merely repeated outputs.','檢查重複輸入，不只檢查重複輸出。'),B(valid?'No input has conflicting outputs.':'The repeated input has conflicting outputs.',valid?'沒有輸入對應互相衝突的輸出。':'同一輸入對應互相衝突的輸出。')],[B('Read each ordered pair as input, output.','每個數對依次表示輸入、輸出。'),B('One output per input is required.','每個輸入須只有一個輸出。'),B('Repeated output values are allowed.','輸出值可重複。')],{kind:'function-relation',pairs,valid},{diagram:{kind:'data-table',headers:[B('x','x'),B('y','y')],rows:pairs}});}
const valueTask=(role,id,ls,k,b,x,expected)=>F(role,id,ls,{k,b,x,request:'value',expected:String(expected),expression:`y=${k}x${b<0?b:'+'+b}`,prompt:B(`For the given relation, find y when ${M(`x=${x}`)}.`,`按所給關係，求 ${M(`x=${x}`)} 時的 y。`),answer:B(M(`y=${expected}`),M(`y=${expected}`)),steps:[B(`Substitute ${M(`x=${x}`)} into the complete relation.`,`把 ${M(`x=${x}`)} 代入完整關係。`),B(`${M(`${k}\\times(${x})+(${b})=${expected}`)}.`,`${M(`${k}\\times(${x})+(${b})=${expected}`)}。`)],answerExpression:`y=${expected}`});
