function formulaTask(role,id,ls,points,k,b,extra={}){return F(role,id,ls,{k,b,points,request:'formula',expected:{k:String(k),b:String(b)},prompt:B(`Find the linear function through ${points.map(p=>M(`(${p[0]},${p[1]})`)).join(' and ')}. Show the equations used to find k and b.`,`求通過 ${points.map(p=>M(`(${p[0]},${p[1]})`)).join(' 與 ')} 的一次函數，寫出求 k、b 所用方程。`),answer:B(M(`y=${k}x${b<0?b:'+'+b}`),M(`y=${k}x${b<0?b:'+'+b}`)),answerExpression:`y=${k}x${b<0?b:'+'+b}`,steps:[B('Substitute both coordinate pairs into y=kx+b.','把兩組坐標代入 y＝kx＋b。'),B(`The solution is ${M(`k=${k},\\ b=${b}`)}; check both points.`,`解得 ${M(`k=${k},\\ b=${b}`)}，再核對兩點。`)],...extra});}
