function centreTask(role,id,ls,values,statistic,expected,fields={}){
 const name=statistic==='mean'?B('mean','平均數'):statistic==='median'?B('median','中位數'):B('mode or modes','眾數');
 const answer=Array.isArray(expected)?expected.length?B(`Modes: ${valueList(expected)}.`,`眾數：${valueList(expected)}。`):B('No mode: every value occurs only once under the repeated-value convention used here.','沒有眾數：按本題須有重複值的約定，各值只出現一次。'):B(M(String(expected)),M(String(expected)));
 return S(role,id,ls,{values,statistic,expected,prompt:B(`Find the ${name.en} of ${valueList(values)}. Show the relevant ordering or calculation.`,`求 ${valueList(values)} 的${name['zh-Hant']}，寫出所需排序或計算。`),answer,steps:statistic==='mean'?[B('Add every observation, then divide by the number of observations.','把所有觀察值相加，再除以個數。'),B(`The result is ${M(String(expected))}.`,`結果為 ${M(String(expected))}。`)]:statistic==='median'?[B('Sort the original observations from smallest to largest.','把原數據從小至大排列。'),B(`Use the middle observation, or the mean of the two middle observations, to obtain ${M(String(expected))}.`,`取中央值，或兩個中央值的平均，得 ${M(String(expected))}。`)]:[B('Count all occurrences and retain every value tied for greatest frequency.','統計出現次數，保留全部同為最高頻數的值。'),B(expected.length?'The listed modes all attain the highest repeated frequency.':'No value is repeated; report no mode under the stated convention.',expected.length?'所列眾數均達最高的重複頻數。':'沒有重複值，按指定約定報告沒有眾數。')],...fields});
}
function weightedTask(role,id,ls,values,frequencies,expected,fields={}){return S(role,id,ls,{values,frequencies,statistic:'weighted-mean',expected:String(expected),prompt:B('Use the given values and weights to find the weighted mean. State the total weight.','根據所列數值及權重求加權平均數，寫出總權重。'),answer:B(M(String(expected)),M(String(expected))),steps:[B('Multiply each value by its weight, add all products, and divide by the sum of the weights.','每個數值乘權重，乘積相加後除以權重總和。'),B(`Total weight=${frequencies.reduce((s,n)=>s+n,0)}; weighted mean=${M(String(expected))}.`,`總權重＝${frequencies.reduce((s,n)=>s+n,0)}；加權平均數＝${M(String(expected))}。`)],diagram:dataTable(values,frequencies),...fields});}
function groupedTask(role,id,ls,bins,expected){const midpoints=bins.map(b=>(b.lo+b.hi)/2),frequencies=bins.map(b=>b.frequency);return S(role,id,ls,{midpoints,frequencies,statistic:'weighted-mean',expected:String(expected),estimate:true,prompt:B('Only the grouped counts are known. Use group midpoints to estimate the mean, and explain why the answer is not necessarily the exact raw-data mean.','只知分組頻數，利用組中值估計平均數，說明為何不一定等於原始數據的精確平均數。'),answer:B(`Estimated mean ${M(String(expected))}; the observations inside each group are unknown.`,`估計平均數為 ${M(String(expected))}；各組內的原始觀察值未知。`),steps:[B(`Group midpoints are ${valueList(midpoints)}.`,`組中值為 ${valueList(midpoints)}。`),B('Weight each midpoint by its group frequency and divide by the total count.','每個組中值乘該組頻數，再除以總個數。')],bins,diagram:{kind:'data-table',headers:[B('Group (lower inclusive, upper exclusive)','組別（含下限、不含上限）'),B('Frequency','頻數')],rows:bins.map(b=>[`[${b.lo},${b.hi})`,b.frequency])}});}
