function varianceTask(role,id,values,expected,fields={}){return S(role,id,[42],{values,statistic:'variance',expected:String(expected),prompt:B(`Find the descriptive variance of ${valueList(values)}, using the number of observations as the denominator. Show the mean first.`,`以觀察值個數作分母，求 ${valueList(values)} 的描述性方差，先寫平均數。`),answer:B(M(`s^{2}=${String(expected).includes('/')?'\\frac{'+String(expected).split('/').join('}{')+'}':expected}`),M(`s^{2}=${String(expected).includes('/')?'\\frac{'+String(expected).split('/').join('}{')+'}':expected}`)),steps:[B('Compute the mean from every observation.','由所有觀察值計算平均數。'),B('Square each deviation from the mean, add, and divide by n.','每項減平均數後平方，相加，再除以 n。'),B(`The variance is ${M(String(expected))}; its unit is the square of the data unit.`,`方差為 ${M(String(expected))}；單位為原數據單位的平方。`)],...fields});}
